<script setup>
import { updateRegistration as wayfinderUpdateRegistration1, index as wayfinderIndex2, update as wayfinderUpdate3 } from './../../../actions/App/Http/Controllers/Staff/AdminWebinarEventController';
import { show as wayfinderShow4 } from './../../../actions/App/Http/Controllers/WebinarEventController';

import { show as manageEventRoute } from '../../../actions/App/Http/Controllers/Staff/AdminWebinarEventController';
import { Link, router, useForm } from '@inertiajs/vue3';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ event: Object, registrations: Object });
const localDateTime = (value, timezone) => {
  const parts = new Intl.DateTimeFormat('sv-SE', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(value));
  return parts.replace(' ', 'T');
};
const form = useForm({ title: props.event.title, slug: props.event.slug, event_type: props.event.event_type, summary: props.event.summary, description: props.event.description, cover_image: props.event.cover_image || '', cover_upload: null, starts_at: localDateTime(props.event.starts_at, props.event.timezone), timezone: props.event.timezone, duration_minutes: props.event.duration_minutes, host_name: props.event.host_name, host_title: props.event.host_title || '', meeting_url: props.event.meeting_url || '', replay_url: props.event.replay_url || '', capacity: props.event.capacity || '', price: (props.event.price_minor / 100).toFixed(2), currency: props.event.currency.toUpperCase(), status: props.event.status });
function status(registration, value) { router.patch(wayfinderUpdateRegistration1.url({ webinarEvent: props.event.id, registration: registration.id }), { status: value }, { preserveScroll: true }); }
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">EVENT MANAGEMENT</div><h1>{{ event.title }}.</h1><p>Edit public details, keep registration information current, and follow attendance.</p></div><Link :href="wayfinderIndex2().url" class="admin-secondary">← All events</Link></div>
  <section class="admin-panel"><h2>Event details</h2><form class="admin-form" @submit.prevent="form.put(wayfinderUpdate3.url({ webinarEvent: event.id }))"><div class="admin-form-grid"><label>Event title<input v-model="form.title" required></label><label>Format<select v-model="form.event_type"><option value="webinar">Webinar</option><option value="workshop">Workshop</option><option value="open_class">Open class</option><option value="community_event">Community event</option></select></label><label>URL slug<input v-model="form.slug" required></label></div><label>Short summary<textarea v-model="form.summary" required maxlength="500" rows="2"></textarea></label><div class="admin-form-grid"><label>Start date and time<input v-model="form.starts_at" type="datetime-local" required></label><label>Timezone<input v-model="form.timezone" required placeholder="Asia/Kolkata"></label></div><div class="admin-form-grid"><label>Host name<input v-model="form.host_name" required></label><label>Host title<input v-model="form.host_title"></label></div><div class="admin-form-grid"><label>Duration in minutes<input v-model="form.duration_minutes" type="number" min="15" max="720" required></label><label>Seat capacity<input v-model="form.capacity" type="number" min="1" placeholder="Unlimited"></label></div><div class="admin-form-grid"><label>Ticket price <small>(0 for free)</small><input v-model="form.price" type="number" min="0" max="999999.99" step="0.01" required></label><label>Currency<select v-model="form.currency"><option value="INR">INR · Indian rupee</option><option value="USD">USD · US dollar</option><option value="EUR">EUR · Euro</option><option value="GBP">GBP · Pound sterling</option></select></label></div><label>Event details<textarea v-model="form.description" required minlength="20" rows="6"></textarea></label><div class="admin-form-grid"><label>Replace cover image<input type="file" accept="image/jpeg,image/png,image/webp" @input="form.cover_upload = $event.target.files[0] || null"><small>Current image is kept unless a new file is selected.</small><small class="admin-form-error">{{ form.errors.cover_upload }}</small></label><label>Live room URL <small>(only visible to registered attendees)</small><input v-model="form.meeting_url" type="url"></label></div><div class="admin-form-grid"><label>Replay URL<input v-model="form.replay_url" type="url"></label><label>Status<select v-model="form.status"><option value="draft">Draft</option><option value="published">Published</option><option value="cancelled">Cancelled</option><option value="completed">Completed</option></select></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="form.processing">Save event</button></div></form></section>
  <section class="admin-panel"><div class="attendee-heading"><div><h2>Registrations</h2><p>{{ registrations.total }} total registrations · attendee contact details are staff-only</p></div><Link :href="wayfinderShow4.url({ event: event.slug })" target="_blank" class="admin-secondary">View public page <UiIcon name="arrow-up-right" :size="12"/></Link></div><div v-for="person in registrations.data" :key="person.id" class="attendee-row"><span class="attendee-avatar">{{ person.name.split(' ').map(part=>part[0]).slice(0,2).join('') }}</span><span class="attendee-main"><b>{{ person.name }}</b><a :href="`mailto:${person.email}`">{{ person.email }}</a><small v-if="person.company">{{ person.company }}</small><small v-if="person.question">Question: {{ person.question }}</small></span><span class="attendee-payment"><b>{{ person.amount_minor ? new Intl.NumberFormat(undefined,{style:'currency',currency:person.currency.toUpperCase()}).format(person.amount_minor/100) : 'Free' }}</b><small>{{ person.payment_status }}</small></span><select :value="person.status" aria-label="Registration status" @change="status(person,$event.target.value)"><option v-if="person.status === 'pending_payment'" disabled value="pending_payment">Payment pending</option><option v-if="person.status === 'payment_failed'" disabled value="payment_failed">Payment failed</option><option value="registered">Registered</option><option value="waitlisted">Waitlisted</option><option value="attended">Attended</option><option value="cancelled">Cancelled</option></select></div><div v-if="!registrations.data.length" class="admin-empty">No one has registered yet.</div><div class="admin-pagination"><span>Page {{ registrations.current_page }} of {{ registrations.last_page }}</span><div><a v-if="registrations.prev_page_url"  :href="manageEventRoute.url({webinarEvent: event.id}, {mergeQuery: {page: registrations.current_page - 1}})">← Newer</a><a v-if="registrations.next_page_url"  :href="manageEventRoute.url({webinarEvent: event.id}, {mergeQuery: {page: registrations.current_page + 1}})">Older →</a></div></div></section>
</StaffAdminLayout></template>

<style scoped>.attendee-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.attendee-heading h2{margin-bottom:4px}.attendee-heading p{margin:0 0 12px;color:var(--academy-muted);font-size:11px}.attendee-row{display:flex;align-items:center;gap:12px;padding:13px 0;border-top:1px solid #efeee9}.attendee-avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:var(--academy-brand-wash);color:var(--academy-secondary);font-size:10px}.attendee-main{display:grid;gap:4px;flex:1}.attendee-main>b{font-size:12px}.attendee-main>a,.attendee-main>small{font-size:10px;color:var(--academy-muted)}.attendee-main>small{max-width:650px;white-space:pre-line}.attendee-payment{display:grid;gap:4px;min-width:72px}.attendee-payment b,.attendee-payment small{font-size:9px}.attendee-payment small{color:var(--academy-muted)}.attendee-row select{padding:8px;border:1px solid #e3e2dc;border-radius:6px;background:var(--academy-surface);font-size:11px}@media(max-width:560px){.attendee-heading{align-items:flex-start;flex-direction:column}.attendee-row{align-items:flex-start;flex-wrap:wrap}.attendee-main{min-width:calc(100% - 50px)}.attendee-row select{margin-left:46px}}</style>
